```python
import asyncio
import json
import os
import re
import sys
import time
from collections import deque
from pathlib import Path

import deepl
from firecrawl import Firecrawl
from firecrawl.v2.types import ScrapeOptions

PROJECT_ROOT = Path(__file__).resolve().parent
OUTPUT_DIRECTORY = PROJECT_ROOT / "barbie"
MAX_FILE_SIZE_BYTES = 50 * 1024 * 1024
REQUEST_TIMEOUT_MILLISECONDS = 300_000
MAX_REQUESTS_PER_MINUTE = 8
MAX_RATE_LIMIT_RETRIES = 8
DEEPL_MAX_TEXT_LENGTH = 120_000
DEEPL_TARGET_LANGUAGE = "EN-US"

request_times: deque[float] = deque()
rate_limit_lock = asyncio.Lock()


def create_firecrawl_client() -> Firecrawl:
    api_key = os.environ.get("FIRECRAWL_API_KEY")
    if not api_key:
        raise RuntimeError("A FIRECRAWL_API_KEY titok nincs beállítva.")
    return Firecrawl(api_key=api_key)


def create_deepl_client() -> deepl.Translator:
    api_key = os.environ.get("DEEPL_API_KEY")
    if not api_key:
        raise RuntimeError("A DEEPL_API_KEY titok nincs beállítva.")
    return deepl.Translator(api_key)


def parse_pdf_sync(client: Firecrawl, input_path: Path) -> str:
    document = client.parse(
        str(input_path),
        options=ScrapeOptions(
            only_main_content=False,
            formats=["markdown"],
            timeout=REQUEST_TIMEOUT_MILLISECONDS,
            parsers=[{"type": "pdf", "mode": "auto"}],
        ),
    )
    markdown = getattr(document, "markdown", None)
    if not isinstance(markdown, str) or not markdown.strip():
        raise RuntimeError("A Firecrawl nem adott vissza Markdown-tartalmat.")
    return markdown


def split_text_for_translation(text: str, max_length: int) -> list[str]:
    if len(text) <= max_length:
        return [text]

    chunks: list[str] = []
    remaining = text

    while remaining:
        if len(remaining) <= max_length:
            chunks.append(remaining)
            break

        split_position = remaining.rfind("\n\n", 0, max_length)
        if split_position <= 0:
            split_position = remaining.rfind("\n", 0, max_length)
        if split_position <= 0:
            split_position = remaining.rfind(". ", 0, max_length)
            if split_position > 0:
                split_position += 1
        if split_position <= 0:
            split_position = remaining.rfind(" ", 0, max_length)
        if split_position <= 0:
            split_position = max_length

        chunks.append(remaining[:split_position])
        remaining = remaining[split_position:]

    return chunks


def translate_markdown_sync(translator: deepl.Translator, markdown: str) -> str:
    chunks = split_text_for_translation(markdown, DEEPL_MAX_TEXT_LENGTH)
    translated_chunks: list[str] = []

    for chunk in chunks:
        if not chunk.strip():
            translated_chunks.append(chunk)
            continue

        result = translator.translate_text(
            chunk,
            target_lang=DEEPL_TARGET_LANGUAGE,
            preserve_formatting=True,
        )
        translated_chunks.append(result.text)

    translated_markdown = "".join(translated_chunks)
    if not translated_markdown.strip():
        raise RuntimeError("A DeepL nem adott vissza lefordított tartalmat.")
    return translated_markdown


async def wait_for_request_slot() -> None:
    while True:
        async with rate_limit_lock:
            now = time.monotonic()

            while request_times and now - request_times[0] >= 60:
                request_times.popleft()

            if len(request_times) < MAX_REQUESTS_PER_MINUTE:
                request_times.append(now)
                return

            wait_seconds = 60 - (now - request_times[0]) + 0.25

        await asyncio.sleep(wait_seconds)


def retry_after_seconds(error: Exception) -> float:
    match = re.search(
        r"retry after\s+(\d+(?:\.\d+)?)s",
        str(error),
        flags=re.IGNORECASE,
    )
    return float(match.group(1)) + 1.0 if match else 60.0


async def parse_with_retries(client: Firecrawl, pdf_path: Path) -> str:
    last_error: Exception | None = None

    for attempt in range(MAX_RATE_LIMIT_RETRIES + 1):
        await wait_for_request_slot()

        try:
            return await asyncio.to_thread(parse_pdf_sync, client, pdf_path)
        except Exception as error:
            if "rate limit exceeded" not in str(error).lower():
                raise

            last_error = error

            if attempt < MAX_RATE_LIMIT_RETRIES:
                await asyncio.sleep(retry_after_seconds(error))

    raise RuntimeError(
        f"A Firecrawl limit {MAX_RATE_LIMIT_RETRIES + 1} próbálkozás után sem oldódott fel: {last_error}"
    ) from last_error


def get_file_size(pdf_path: Path) -> int:
    return pdf_path.stat().st_size


def write_json_atomically(json_path: Path, data: dict[str, object]) -> None:
    temporary_path = json_path.with_name(f"{json_path.name}.tmp")
    temporary_path.write_text(
        json.dumps(data, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    os.replace(temporary_path, json_path)


async def process_pdf(
    firecrawl_client: Firecrawl,
    deepl_client: deepl.Translator,
    pdf_path: Path,
) -> tuple[Path, str | None]:
    try:
        file_size = await asyncio.to_thread(get_file_size, pdf_path)

        if file_size > MAX_FILE_SIZE_BYTES:
            return pdf_path, "A fájl mérete meghaladja az 50 MB-os Firecrawl korlátot."

        if file_size == 0:
            return pdf_path, "Az üres PDF nem dolgozható fel."

        markdown = await parse_with_retries(firecrawl_client, pdf_path)
        translated_markdown = await asyncio.to_thread(
            translate_markdown_sync,
            deepl_client,
            markdown,
        )

        json_path = OUTPUT_DIRECTORY / f"{pdf_path.stem}.json"
        output_data: dict[str, object] = {
            "source_file": pdf_path.name,
            "source_path": str(pdf_path.resolve()),
            "source_size_bytes": file_size,
            "format": "markdown",
            "target_language": DEEPL_TARGET_LANGUAGE,
            "content": translated_markdown,
        }

        await asyncio.to_thread(write_json_atomically, json_path, output_data)
        return pdf_path, None
    except Exception as error:
        return pdf_path, str(error)


async def main() -> int:
    try:
        firecrawl_client = create_firecrawl_client()
        deepl_client = create_deepl_client()
    except RuntimeError as error:
        print(f"HIBA: {error}", file=sys.stderr)
        return 1

    OUTPUT_DIRECTORY.mkdir(parents=True, exist_ok=True)

    pdf_paths = sorted(
        path
        for path in PROJECT_ROOT.iterdir()
        if path.is_file()
        and path.suffix.lower() == ".pdf"
        and not (OUTPUT_DIRECTORY / f"{path.stem}.json").exists()
    )

    if not pdf_paths:
        print("Nincs feldolgozandó PDF a projekt gyökérmappájában.")
        return 0

    print(
        f"{len(pdf_paths)} PDF feldolgozása indul, legfeljebb "
        f"{MAX_REQUESTS_PER_MINUTE} Firecrawl kérés/perc ütemezéssel."
    )

    results = await asyncio.gather(
        *(
            process_pdf(firecrawl_client, deepl_client, pdf_path)
            for pdf_path in pdf_paths
        )
    )

    failures = [(path, error) for path, error in results if error]

    for path, error in failures:
        print(f"HIBA: {path.name}: {error}", file=sys.stderr)

    print(
        f"Sikeres: {len(results) - len(failures)}. "
        f"Hibás: {len(failures)}. "
        f"Kimenet: {OUTPUT_DIRECTORY}"
    )

    return 1 if failures else 0


if __name__ == "__main__":
    raise SystemExit(asyncio.run(main()))
